import * as T from './vendor/three.webgpu.min.js';
import {WebGLRenderer} from './vendor/three.module.min.js';
import {graphicsProfile,createCompatibleRenderer,renderPixelRatio,rendererBackend} from './renderer-policy.js';
import {installPinkWarsSoldier} from './level2-player.js';
import {poseUnarmedForInspection} from './rlh-firefighter.js';
import {createGlove} from './hands.js';
import {ARMOR_STAGES} from './armor-progression.js';
const $=id=>document.getElementById(id),section=document.querySelector('section'),canvas=document.querySelector('canvas'),params=new URLSearchParams(location.search),rigs=[];
let scene,renderer,camera,stage=1,angle=Math.PI,drag=null,focus=0,ready=false;
for(const s of ARMOR_STAGES){const b=document.createElement('button');b.textContent=s.level+' · '+s.name;b.dataset.stage=s.level;b.onclick=()=>select(s.level);document.querySelector('nav').append(b);}
function select(n){stage=n;const s=ARMOR_STAGES[n-1];for(const r of rigs){r.model.setLevel(n);poseUnarmedForInspection(r.model,r.gloves);}for(const b of document.querySelectorAll('[data-stage]'))b.setAttribute('aria-pressed',String(Number(b.dataset.stage)===n));$('title').textContent='STADE '+n+' / 5 — '+s.name.toUpperCase();$('description').textContent=s.description;$('unlock').textContent=n===1?'Tenue de départ · aucune nanoparticule requise':'Plan à récupérer au niveau '+s.chapter+' · fabrication à l’atelier : '+s.cost.toLocaleString('fr-FR')+' NP · bouclier '+s.shield+' · résistance santé +'+Math.round((1-s.resistance)*100)+' %';}
async function boot(){try{
 const graphics=graphicsProfile({userAgent:navigator.userAgent,platform:navigator.platform,maxTouchPoints:navigator.maxTouchPoints,gpu:navigator.gpu,rendererHint:params.get('renderer')},'balanced'),made=await createCompatibleRenderer({canvas,WebGPU:T.WebGPURenderer,WebGL:WebGLRenderer,profile:graphics});renderer=made.renderer;scene=new T.Scene();scene.background=new T.Color(0x101824);scene.add(new T.HemisphereLight(0xdce9ff,0x292430,2));const sun=new T.DirectionalLight(0xffffff,3.5);sun.position.set(-3,5,4);scene.add(sun);const rim=new T.DirectionalLight(0x8ec7ff,2);rim.position.set(3,3,-4);scene.add(rim);
 const env=document.createElement('canvas');env.width=256;env.height=128;const c=env.getContext('2d');c.fillStyle='#607285';c.fillRect(0,0,256,128);c.fillStyle='#edf4ff';c.fillRect(0,20,256,25);c.fillStyle='#19202a';c.fillRect(0,90,256,38);const texture=new T.CanvasTexture(env);texture.colorSpace=T.SRGBColorSpace;texture.mapping=T.EquirectangularReflectionMapping;scene.environment=texture;scene.environmentIntensity=.65;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1;
 camera=new T.PerspectiveCamera(37,1,.05,80);
 for(const[hero,x]of[['ghju',.64],['lylu',-.64]]){const r=await installPinkWarsSoldier(T,scene,hero);await Promise.all([r.model.shadowUnit.gear.ready,r.model.shadowUnit.suit.ready,r.model.shadowUnit.outfits.ready]);r.model.root.visible=true;r.model.root.position.x=x;r.gloves=[createGlove(r.kit.gloves,{mirror:true,sleeve:false,arm:false}),createGlove(r.kit.gloves,{sleeve:false,arm:false})];r.model.root.add(...r.gloves);rigs.push(r);const disk=new T.Mesh(new T.CylinderGeometry(.51,.55,.055,48),new T.MeshStandardMaterial({color:0x263343,roughness:.4,metalness:.6}));disk.position.set(x,-.035,0);scene.add(disk);const ring=new T.Mesh(new T.TorusGeometry(.51,.008,6,64),new T.MeshBasicMaterial({color:hero==='ghju'?0xff148b:0x51b5ff}));ring.rotation.x=-Math.PI/2;ring.position.set(x,-.004,0);scene.add(ring);}
 ready=true;$('status').hidden=true;select(1);resize();renderer.setAnimationLoop(frame);
 }catch(e){$('status').hidden=false;$('status').textContent=e.message;console.error(e);}}
function resize(){if(!renderer)return;const w=section.clientWidth,h=section.clientHeight;renderer.setSize(w,h);renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));camera.aspect=w/h;camera.updateProjectionMatrix();}
function frame(){if(!ready)return;const portrait=section.clientWidth/section.clientHeight<.9,fx=focus===1?.64:focus===2?-.64:0,distance=portrait?(focus?3.8:6.5):4.5;camera.position.set(fx+Math.sin(angle)*distance,1.13,Math.cos(angle)*distance);camera.lookAt(fx,.9,0);camera.updateMatrixWorld();const w=section.clientWidth,h=section.clientHeight;for(const[i,r]of rigs.entries()){const v=new T.Vector3(r.model.root.position.x,-.08,0).project(camera),label=document.querySelectorAll('.names span')[i];label.style.position='absolute';label.style.left=(v.x*.5+.5)*w+'px';label.style.top=Math.min(h-24,(.5-v.y*.5)*h+12)+'px';label.style.transform='translateX(-50%)';label.hidden=Math.abs(v.x)>1.1;}renderer.render(scene,camera);}
canvas.addEventListener('pointerdown',e=>{drag={id:e.pointerId,x:e.clientX};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(drag?.id!==e.pointerId)return;angle-=(e.clientX-drag.x)*.008;drag.x=e.clientX;});for(const ev of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>drag=null);
$('front').onclick=()=>angle=Math.PI;$('back').onclick=()=>angle=0;$('hero').onclick=()=>focus=(focus+1)%3;addEventListener('resize',resize);
window.__PINK_OUTFITS={select,snapshot:()=>({ready,stage,backend:renderer&&rendererBackend(renderer),heroes:rigs.map(r=>({id:r.character.id,...r.model.shadowUnit.outfits.snapshot()}))}),get renderer(){return renderer;},get scene(){return scene;},get camera(){return camera;}};void boot();
